220		 * Sets the {@link #thumbsUpPercentage}, i.e. the percentage of people that thumbs-up this video
221		 * (format:  "<percentage>%").
222		 *
223		 * @param likedCountInt	Total number of "likes".
224		 * @param dislikedCountInt Total number of "dislikes".
225		 */
226		public void setLikeDislikeCount(Long likedCountInt, Long dislikedCountInt) {
227			this.thumbsUpPercentage = -1;
228	
229			// Logger.d(this, "setLikeDislikeCount "+likedCountInt+" "+dislikedCountInt +" -> "+likeCountNumber+" "+dislikeCountNumber);
230			final Long likes = filterNegative(likedCountInt);
231			final Long dislikes = filterNegative(dislikedCountInt);
232	
233			// some videos do not allow users to like/dislike them:  hence likedCountInt / dislikedCountInt
234			// might be null in those cases
235			if (likes != null && dislikes != null) {
236	
237				long likedCount = likes;
238				long dislikedCount = dislikes;
239				long totalVoteCount = likedCount + dislikedCount;	// liked and disliked counts
240	
241				if (totalVoteCount != 0) {
242					this.thumbsUpPercentage = (int) Math.round((double)likedCount*100/totalVoteCount);
243	
244				}
245			}
246			this.likeCountNumber = likes;
247			this.dislikeCountNumber = dislikes;
248		}
