263		private void setIsLiveStream() {
264			// is live stream?
265			if (duration.equals("0:00")) {
266				isLiveStream = true;
267				duration = getStr(R.string.LIVE);
268				// set publishDate to current (as there is a bug in YouTube API in which live videos's date is incorrect)
